import json
import pandas as pd
import numpy as np

FIELDS = ["name", "email", "created_date", "status"]
SOURCES = ["source_a", "source_b", "source_c"]


def is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and np.isnan(v):
            return True
    except Exception:
        pass
    try:
        return bool(pd.isna(v))
    except Exception:
        return False


def norm_id(v):
    if is_null(v):
        return None
    try:
        f = float(str(v).strip())
        if f.is_integer():
            return int(f)
    except Exception:
        return None
    return None


def norm_str(v):
    if is_null(v):
        return None
    s = str(v).strip()
    return s if s else None


def norm_date(v):
    if is_null(v):
        return None
    ts = pd.to_datetime(str(v).strip(), errors="coerce")
    if pd.isna(ts):
        return None
    return ts.strftime("%Y-%m-%d")


def norm_status(v):
    if is_null(v):
        return None
    if isinstance(v, (bool, np.bool_)):
        return "active" if bool(v) else "inactive"
    s = str(v).strip().lower()
    if s in ("true", "t", "1", "yes", "y", "active"):
        return "active"
    if s in ("false", "f", "0", "no", "n", "inactive"):
        return "inactive"
    if s in ("", "nan", "none", "null"):
        return None
    return s


def load_source(src):
    if src == "source_a":
        raw = pd.read_json("/data/source_a/users.json")
        colmap = {"id": "user_id", "full_name": "name", "email": "email",
                  "registration_date": "created_date", "status": "status"}
    elif src == "source_b":
        raw = pd.read_csv("/data/source_b/users.csv", dtype=str)
        colmap = {"user_id": "user_id", "name": "name", "email_address": "email",
                  "created_at": "created_date", "is_active": "status"}
    else:
        raw = pd.read_parquet("/data/source_c/users.parquet")
        colmap = {"userId": "user_id", "userName": "name", "email": "email",
                  "joined": "created_date", "active": "status"}

    df = raw.rename(columns=colmap)
    records = {}
    for _, row in df.iterrows():
        uid = norm_id(row.get("user_id"))
        if uid is None:
            continue
        rec = {
            "name": norm_str(row.get("name")),
            "email": norm_str(row.get("email")),
            "created_date": norm_date(row.get("created_date")),
            "status": norm_status(row.get("status")) if "status" in df.columns else None,
        }
        records[uid] = rec
    return records


records = {src: load_source(src) for src in SOURCES}

all_ids = sorted(set().union(*[set(r.keys()) for r in records.values()]))

merged = {}
for uid in all_ids:
    row = {}
    for field in FIELDS:
        for src in SOURCES:  # priority order
            val = records[src].get(uid, {}).get(field)
            if val is not None:
                row[field] = val
                break
        row.setdefault(field, None)
    merged[uid] = row

conflicts = []
for uid in all_ids:
    for field in FIELDS:
        vals = {}
        for src in SOURCES:
            if uid in records[src]:
                v = records[src][uid].get(field)
                if v is not None:
                    vals[src] = v
        if len(set(vals.values())) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": vals,
                "selected": merged[uid][field],
            })

out = pd.DataFrame([
    {
        "user_id": uid,
        "name": merged[uid]["name"],
        "email": merged[uid]["email"],
        "created_date": merged[uid]["created_date"],
        "status": merged[uid]["status"],
    }
    for uid in all_ids
], columns=["user_id", "name", "email", "created_date", "status"])
out["user_id"] = out["user_id"].astype("int64")
for c in ["name", "email", "created_date", "status"]:
    out[c] = out[c].astype("object")

out.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2)

print("rows:", len(out))
print(out.to_string())
print("total_conflicts:", len(conflicts))
print(json.dumps(report, indent=2))
